WITH cleaned AS (SELECT *, SUBSTRING(account_type, 1, 2) AS account_type_prefix, COALESCE(status, 'DIRECT') AS status_filled FROM accounts WHERE status IS NOT NULL AND status IS NOT DISTINCT FROM 'FROZEN') SELECT DATE_TRUNC('MONTH', opened_date) AS activity_month, COUNT(DISTINCT customer_id) AS distinct_customer_ids, ROUND(SUM(balance) / NULLIF(COUNT(CASE WHEN status = 'OPEN' THEN 1 END), 0), 2) AS balance_per_open, ROUND(AVG(balance), 2) AS avg_balance FROM cleaned GROUP BY 1 ORDER BY distinct_customer_ids ASC;
